import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Desktop Core Port","description":"","frontmatter":{"epic":12,"title":"Desktop Core Port","status":"✅ Done — tasks 12.1–12.7, 12.7a, 12.8, 12.9, 12.10 all done","scope":"desktop","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/desktop/core-port.md"},"headers":[],"relativePath":"sovereign-edge/epics/desktop/core-port.md","filePath":"sovereign-edge/epics/desktop/core-port.md"}'),n={name:"sovereign-edge/epics/desktop/core-port.md"};function c(r,e,d,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="epic-desktop-core-port" tabindex="-1">Epic: Desktop Core Port <a class="header-anchor" href="#epic-desktop-core-port" aria-label="Permalink to &quot;Epic: Desktop Core Port&quot;">​</a></h1><blockquote><p>Bring Phase 1/2 mobile functionality — inference engine, connector framework, a minimal chat UI — to desktop, on the shell decided in <a href="./shell.html">Desktop Shell</a>.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Secondary, optional desktop client. Sequenced after the mobile MVP proves the concept, not built in parallel with it — per the developer&#39;s decision, desktop as a whole is deliberately deferred. This epic holds that eventual work; <a href="./shell.html">Desktop Shell</a> (epic 9) held only the technology decision that unblocks it.</p><p>Not started. Unblocked in principle now that epic 9 is resolved (Tauri v2, see <a href="./../../research/0010-desktop-shell-technology.html">research 0010</a>), but whether this or mobile&#39;s own remaining Phase 1 item (task 0.1.20, store release setup) is scheduled next is an open call — see <code>ROADMAP.md</code>, and this repo&#39;s own &quot;one task at a time, sequenced&quot; convention in the root <code>AGENTS.md</code>.</p><p><strong>Task breakdown below mirrors mobile&#39;s own granularity</strong> (Core Inference &amp; Chat: 6 tasks; Connector Framework: 6 tasks) rather than the single monolithic task this epic started with — sized so each is independently implementable and reviewable, per the root <code>AGENTS.md</code>&#39;s &quot;implement a single task, verify its review checklist, then stop for human review.&quot; Each task below is grounded in something research 0010 already decided (the <code>EngineAdapter</code>, <code>SecureStorageAdapter</code>, and Tier 3 native-handler-registry shapes it names explicitly); none of this breakdown invents a new architectural decision that doc didn&#39;t already make.</p><p><strong>Deliberately out of scope for this epic:</strong> a full desktop app shell — navigation, settings screens, per-connector permission UI — the desktop equivalent of <a href="./../mobile/mobile-app-shell.html">Mobile App Shell</a> (epic 8). Task 12.7 below includes only the minimal chat surface needed to verify 12.2–12.6 end to end, the same role mobile&#39;s own task 1.3 (offline chat UI) plays inside Core Inference &amp; Chat rather than inside its own App Shell epic. A real desktop app shell is future, unscoped work — its own epic once there&#39;s a reason to build it, not invented speculatively here.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-12-1-—-tauri-app-scaffold-and-build-tooling" tabindex="-1">✅ 12.1 — Tauri app scaffold and build tooling <a class="header-anchor" href="#✅-12-1-—-tauri-app-scaffold-and-build-tooling" aria-label="Permalink to &quot;✅ 12.1 — Tauri app scaffold and build tooling&quot;">​</a></h4><p><strong>Goal:</strong> Stand up the Tauri project this whole app is built on, the desktop equivalent of mobile&#39;s own task 0.1 (repo scaffold) and 0.3 (native build tooling) combined into one task rather than a separate infrastructure epic — desktop doesn&#39;t yet have enough surface to justify its own epic 0.</p><p><strong>Deliverables:</strong></p><ul><li><code>apps/desktop</code>&#39;s <code>src-tauri/</code> Rust project plus its React DOM frontend scaffold, wired into the existing pnpm workspace.</li><li>A capabilities/permissions skeleton (empty allow-list to start — Tauri v2&#39;s default-deny posture per research 0010), not a populated one; populated by tasks 12.3 and 12.5 as they add real commands.</li><li>Dev and build tooling for macOS, Windows, and Linux; a CI smoke build for at least macOS (matching whatever the mobile CI&#39;s own platform-coverage precedent is).</li><li>Shared TS/ESLint/Prettier config extended to cover <code>apps/desktop</code>, plus a <code>rustfmt</code>/<code>clippy</code> baseline for the new Rust surface — this repo&#39;s first.</li></ul><p><strong>Dependencies:</strong> Epic 9 (Desktop Shell) decision.</p><p><strong>Review checklist:</strong></p><ul><li>A fresh clone can build and launch an empty Tauri window on macOS, Windows, and Linux following only this task&#39;s own setup docs.</li><li>CI fails loudly on a Rust compile error or lint failure, the same &quot;must fail loudly, not silently pass&quot; bar the root <code>AGENTS.md</code> sets for the zero-network CI check.</li></ul><p><code>apps/desktop/src-tauri/</code> (Rust, Cargo.toml/build.rs/lib.rs/main.rs) plus a Vite + React DOM frontend (<code>index.html</code>, <code>vite.config.ts</code>, <code>src/App.tsx</code>), identifier <code>fs.sovereign.edge.desktop</code>, icons generated from <code>apps/mobile/assets/icon.png</code> via <code>tauri icon</code> for brand consistency rather than a placeholder. <code>capabilities/default.json</code> grants only <code>core:default</code> — nothing app-specific yet, per this task&#39;s own &quot;empty allow-list&quot; deliverable. Root <code>package.json</code>&#39;s <code>lint</code>/<code>typecheck</code>/<code>test</code> scripts changed from <code>pnpm --filter mobile ...</code> to <code>pnpm -r --if-present ...</code> so <code>ci.yml</code> covers both apps without its own changes; <code>apps/mobile</code>&#39;s own scripts (<code>ios</code>, <code>android</code>, <code>check:offline</code>) are untouched.</p><p><strong>Verified on macOS, not on Windows or Linux — flagged rather than assumed.</strong><code>cargo fmt --check</code>, <code>cargo clippy --all-targets -- -D warnings</code>, <code>pnpm tauri build --debug --no-bundle</code>, and the launch-smoke script (<code>scripts/ci/launch-smoke.js</code> — spawns the built binary, fails if it exits within 5s, mirroring native.yml&#39;s own &quot;still running N seconds later&quot; bar for mobile) all ran clean locally on macOS during this task. <code>desktop.yml</code>&#39;s Windows and Linux jobs were written against Tauri&#39;s own documented CI recipe (the exact <code>apt</code> package list — <code>libwebkit2gtk-4.1-dev</code>, <code>libayatana-appindicator3-dev</code>, <code>librsvg2-dev</code>, <code>patchelf</code>, plus <code>xvfb-run</code> to give the Linux runner a display to launch into) but have not actually run on those platforms yet — no Windows or Linux machine was available to this task. First real signal on those two legs is whichever push to <code>main</code> first triggers <code>desktop.yml</code>; treat a Windows/Linux failure there as this task&#39;s own gap, not a regression in unrelated work.</p><hr><h4 id="✅-12-2-—-rust-llama-cpp-engineadapter-and-model-manager" tabindex="-1">✅ 12.2 — Rust <code>llama.cpp</code> <code>EngineAdapter</code> and model manager <a class="header-anchor" href="#✅-12-2-—-rust-llama-cpp-engineadapter-and-model-manager" aria-label="Permalink to &quot;✅ 12.2 — Rust `llama.cpp` `EngineAdapter` and model manager&quot;">​</a></h4><p><strong>Goal:</strong> On-device GGUF inference on desktop, mirroring mobile&#39;s task 1.1 (<code>llama.rn</code> integration) and 1.2 (model manager).</p><p><strong>Deliverables:</strong></p><ul><li>An <code>EngineAdapter</code> around a Rust <code>llama.cpp</code> binding (final crate choice — <code>llama-cpp-2</code>, <code>llama_cpp-rs</code>, or a bundled <code>llama-server</code> — is this task&#39;s to make; research 0010 deliberately left it open).</li><li>A desktop model manager: download, verify, and select a GGUF model, reusing <code>packages/core</code>&#39;s model-descriptor shape once that extraction happens, or mirroring <code>apps/mobile/src/models/</code> closely if it hasn&#39;t yet.</li></ul><p><strong>Dependencies:</strong> Task 12.1.</p><p><strong>Review checklist:</strong></p><ul><li>A real GGUF model loads and generates a reply on-device on at least macOS — this repo&#39;s own verification convention (exercise the behavior, not just the exit code) applies here exactly as it did for <code>llama.rn</code> on mobile.</li><li>No network call happens on the inference path itself — only the explicit, user-initiated model download does, per the root <code>AGENTS.md</code>&#39;s hard architectural rule 1 and its rule-3 exception.</li></ul><p><strong>Decided: <code>llama-cpp-2</code></strong> (the <code>utilityai/llama-cpp-rs</code> project), Metal enabled on macOS only via a target-gated Cargo dependency — CPU-only elsewhere for now, matching mobile&#39;s Metal-on-iOS split. Rejected <code>llama_cpp-rs</code> (thinner, less active) and a bundled <code>llama-server</code> subprocess (an IPC layer with no benefit here; in-process bindings keep this port structurally parallel to how <code>llama.rn</code> is used on mobile).</p><p><code>apps/desktop/src-tauri/src/engine/</code> (<code>types.rs</code>, <code>adapter.rs</code>) mirrors <code>apps/mobile/src/chat/inference/</code>&#39;s <code>InferenceEngine</code> invariants (one context at a time, streaming per-token callback, cancellation, chat-template prompting) using <code>llama-cpp-2</code>&#39;s <code>LlamaBackend</code>/<code>LlamaModel</code>/<code>LlamaContext</code>, with <code>self_cell</code> to hold the model and its borrowed context together safely. <code>apps/desktop/src-tauri/src/models/</code> (<code>types.rs</code>, <code>catalog.rs</code>, <code>store.rs</code>, <code>hashing.rs</code>, <code>verify.rs</code>, <code>download.rs</code>, <code>device.rs</code>, <code>manager.rs</code>) mirrors <code>apps/mobile/src/models/</code> closely, per this epic&#39;s own instruction, since <code>packages/core</code>&#39;s extraction still hasn&#39;t happened. <code>lib.rs</code> registers the minimal Tauri command set (<code>list_models</code>, <code>install_model</code>, <code>load_model</code>, <code>generate</code> with streaming events, <code>cancel_generation</code>, <code>unload_model</code>, <code>engine_info</code>, etc.) plus a best-effort startup bootstrap that loads the last-used model, mirroring mobile&#39;s <code>ModelSessionProvider</code>.</p><p><strong>Two deliberate deviations from mobile, both documented in-code:</strong><code>llama-cpp-2</code>&#39;s <code>LlamaModelLoadError</code> carries no message text at all, so mobile&#39;s regex-on-error-message technique for distinguishing &quot;out of memory&quot; from &quot;the file is broken&quot; isn&#39;t portable as-is; <code>engine/adapter.rs</code> instead does a preflight RAM-budget check reusing <code>models::device</code>&#39;s own fit formula. Separately, <code>capabilities/default.json</code> now notes that Tauri v2&#39;s ACL only gates <em>plugin</em>-provided commands by default — this task&#39;s own app-registered commands are reachable without a capability entry unless the app opts into gating them via <code>build.rs</code>, which isn&#39;t wired up yet; flagged there as a gap for task 12.5 (Tier 3 native handlers) to close, not silently assumed.</p><p><strong>Verified on macOS, not on Windows or Linux — flagged rather than assumed,</strong> the same gap 12.1 recorded. <code>cargo fmt --check</code> and <code>cargo clippy --all-targets -- -D warnings</code> ran clean. <code>apps/desktop/src-tauri/tests/engine_smoke.rs</code> (<code>#[ignore]</code>d — it downloads a real ~490MB model) downloaded, verified, and loaded the catalog&#39;s smallest model (Qwen2.5 0.5B) through the real <code>EngineAdapter</code> and generated an actual reply on-device with Metal GPU offload active: <code>loaded: gpu=true reason_no_gpu=None context_size=2048</code> / <code>reply (Eos, 2 tokens, Some(31)ms to first token): &quot;Hello!&quot;</code>. A grep of <code>src/engine/</code> confirms zero network-crate references in the inference path.</p><hr><h4 id="✅-12-3-—-securestorageadapter-over-the-os-credential-store" tabindex="-1">✅ 12.3 — <code>SecureStorageAdapter</code> over the OS credential store <a class="header-anchor" href="#✅-12-3-—-securestorageadapter-over-the-os-credential-store" aria-label="Permalink to &quot;✅ 12.3 — `SecureStorageAdapter` over the OS credential store&quot;">​</a></h4><p><strong>Goal:</strong> Per-connector credential isolation on desktop, mirroring what <code>apps/mobile/src/connectors/permissions/vault.ts</code> already guarantees on mobile.</p><p><strong>Deliverables:</strong></p><ul><li>A <code>SecureStorageAdapter</code> Tauri plugin over macOS Keychain, Windows Credential Manager, and Linux Secret Service.</li><li>The same &quot;cannot, not should not&quot; isolation property <code>vault.ts</code> documents: no exported function takes a connector ID and a key directly: only a handle scoped to one connector&#39;s own namespace.</li></ul><p><strong>Dependencies:</strong> Task 12.1.</p><p><strong>Review checklist:</strong></p><ul><li>A credential written for one connector is unreachable through another connector&#39;s handle — the same test <code>permissions/grants.test.ts</code> already runs for mobile, ported rather than redesigned.</li><li>Revoking a connector destroys its stored credential, matching <code>permissions/grants.ts</code>&#39;s <code>revoke()</code> behavior exactly.</li></ul><p><strong>Decided: <code>keyring</code> v3.6.3</strong> (not the newer v4 <code>keyring-core</code> redesign — v3&#39;s <code>Entry::new</code>/<code>set_password</code>/<code>get_password</code>/<code>delete_credential</code> API is the long-stable one, and its MSRV, 1.75, is already below this crate&#39;s own floor). Target-gated Cargo features per OS, mirroring 12.2&#39;s <code>llama-cpp-2</code> split: <code>apple-native</code> (macOS), <code>windows-native</code> (Windows), <code>sync-secret-service</code> (Linux) — the same three backends research 0010 named.</p><p><strong>Not a separate Tauri plugin crate</strong>, despite <code>core-port.md</code>&#39;s own &quot;Tauri plugin&quot; phrasing above: mobile&#39;s <code>openVault</code> is never called from UI code either — its only caller is <code>connectors/runtime/execute.ts</code>, internal Rust-side business logic (task 12.4&#39;s connector runtime), never IPC from the WebView. A plain Rust module (<code>apps/desktop/src-tauri/src/secure_storage/</code>) needs no command/capability surface, so the formal plugin machinery would be unused ceremony. Documented as a deliberate scope call in-code, the same way 12.2 flagged its own deviations.</p><p><code>secure_storage/vault.rs</code> ports <code>vault.ts</code>&#39;s <code>ConnectorVault</code>/<code>openVault</code> directly: same <code>SAFE_SEGMENT</code>-equivalent charset check, same single-namespace-plus-composite-key isolation shape (<code>keyring</code> &quot;service&quot; = a fixed <code>sovereign.connector</code> constant, &quot;username&quot; = <code>&lt;connectorId&gt;.&lt;credentialKey&gt;</code>), same <code>Ok(None)</code>-on-missing / no-throw-on-missing-key-delete semantics as <code>SecureStore</code>. <strong>Note:</strong><code>grants.ts</code>&#39;s own port — the grant/consent state machine whose <code>revoke()</code> calls this vault&#39;s <code>clear()</code> — is task 12.4&#39;s deliverable, not this one; 12.3 delivers the vault primitive only, per <code>core-port.md</code>&#39;s own task-4 deliverable list (&quot;reused as-is, backed by task 12.3&#39;s <code>SecureStorageAdapter</code>&quot;).</p><p><strong>Verified on macOS, not on Windows or Linux — flagged rather than assumed,</strong> the same gap 12.1 and 12.2 recorded. <code>cargo fmt --check</code> and <code>cargo clippy --all-targets -- -D warnings</code> ran clean. Two test tiers, both run and both green: <code>cargo test --lib secure_storage</code> (7 tests, mock-backed via <code>keyring::mock</code> — fast, no real OS access) and <code>apps/desktop/src-tauri/tests/vault_smoke.rs</code> (<code>#[ignore]</code>d — writes real entries into this machine&#39;s actual macOS Keychain, verifies isolation between two connectors sharing one credential key, verifies <code>clear()</code> destroys the credential, then deletes its own scratch entries regardless of pass/fail): <code>test isolates_and_destroys_credentials_in_the_real_keychain ... ok</code>.</p><hr><h4 id="✅-12-4-—-connector-framework-port-tier-1" tabindex="-1">✅ 12.4 — Connector framework port (Tier 1) <a class="header-anchor" href="#✅-12-4-—-connector-framework-port-tier-1" aria-label="Permalink to &quot;✅ 12.4 — Connector framework port (Tier 1)&quot;">​</a></h4><p><strong>Goal:</strong> The manifest schema, permission model, and Tier 1 (HTTP) runtime dispatch work on desktop unchanged — this epic&#39;s own review checklist from before the breakdown.</p><p><strong>Deliverables:</strong></p><ul><li><code>executeConnectorCall</code>&#39;s <code>case 1</code> (HTTP request/response templating) built against desktop&#39;s own <code>fetch</code>, with the manifest schema and cross-field validation (<code>manifest/schema.ts</code>, <code>manifest/validate.ts</code>) reused as-is — no desktop-specific fork.</li><li>The grant/consent state machine and generalized granted-scope concept (<code>permissions/grants.ts</code>, task 2.6) reused as-is, backed by task 12.3&#39;s <code>SecureStorageAdapter</code> instead of <code>expo-secure-store</code>.</li></ul><p><strong>Dependencies:</strong> Tasks 12.2, 12.3.</p><p><strong>Review checklist:</strong></p><ul><li>The Search connector&#39;s existing manifest (<code>apps/mobile/src/connectors/search/manifest.ts</code>) executes a real request/response round trip on desktop with zero changes to the manifest itself — this epic&#39;s original, defining review bar.</li></ul><p><code>apps/desktop/src-tauri/src/connectors/</code> (new, <code>pub mod</code>, mirroring <code>apps/mobile/src/connectors/</code>&#39;s own directory split): <code>manifest/</code> (serde structs with <code>#[serde(deny_unknown_fields)]</code> mirroring Zod&#39;s <code>.strict()</code>; <code>ValueSource</code>/<code>PathPart</code> as <code>#[serde(untagged)]</code> enums; <code>ConnectorManifest</code> parsed by peeking <code>tier</code> rather than serde&#39;s own tagging, since Zod&#39;s <code>discriminatedUnion(&#39;tier&#39;, ...)</code> uses a numeric field serde&#39;s internal tagging can&#39;t match directly), <code>permissions/grants.rs</code> (the state machine, taking <code>grants_dir: &amp;Path</code> explicitly rather than mobile&#39;s implicit global path — mirrors <code>models::store</code>&#39;s own pattern — and calling task 12.3&#39;s <code>secure_storage::open_vault</code> on <code>revoke()</code>, exactly like mobile calls <code>openVault</code> internally), <code>runtime/execute.rs</code> (split into pure <code>build_request</code>/<code>map_response</code> functions plus an async <code>dispatch</code>, unlike mobile&#39;s single <code>fetch</code>-mocked function — this is what let the real <code>search.manifest.json</code> fixture&#39;s request construction be asserted byte-for-byte with no server involved). <code>manifest/fixtures.rs</code> embeds the literal mobile fixture via <code>include_str!</code>, not a copy, so &quot;zero changes to the manifest itself&quot; is a build-time guarantee rather than a promise to keep two files in sync by hand. No new Tauri commands and no new Cargo dependencies — same call 12.3 made (nothing on mobile calls this from UI code either; <code>reqwest</code>+<code>serde_json</code> already covered everything needed).</p><p><strong>Known, inherited quirk, ported not fixed</strong> (<code>core-port.md</code> says reuse unchanged): <code>execute.ts</code>&#39;s credential-key prefetch only scans <code>request.headers</code>/<code>request.body</code>, never <code>request.query</code> — a <code>credential</code><code>ValueSource</code> inside <code>query</code> (structurally legal, though the validator rejects it and no fixture uses one) would always resolve <code>missing-credential</code> regardless of vault contents. Documented in <code>runtime/execute.rs</code>&#39;s own doc comment, not silently corrected.</p><p><strong>Verified on macOS, not on Windows or Linux — flagged rather than assumed,</strong> the same gap 12.1–12.3 recorded. <code>cargo fmt --check</code> and <code>cargo clippy --all-targets -- -D warnings</code> ran clean. Three test tiers: (1) <code>cargo test --lib</code> — 41 tests, porting <code>validate.test.ts</code>&#39;s cross-field cases (including the real <code>search.manifest.json</code> fixture validating unchanged), <code>execute.test.ts</code>&#39;s request-building/response-mapping cases against that same real fixture, and <code>grants.test.ts</code>&#39;s isolation/revoke cases, all mock-backed for speed; (2) <code>apps/desktop/src-tauri/tests/connector_dispatch.rs</code> — <strong>not</strong> <code>#[ignore]</code>d — a real <code>tokio::net::TcpListener</code> on <code>127.0.0.1</code> serving one fixed HTTP response, dispatched through the real <code>execute_connector_call</code> end to end (real TCP, real HTTP, real JSON mapping) on a scratch manifest, since <code>search.manifest.json</code>&#39;s own origin (<code>https://searx.example.org</code>) is RFC 2606&#39;s reserved, non-resolving example domain and cannot be dialed for real without rewriting the fixture under test: <code>test dispatches_a_real_request_over_real_tcp_and_maps_the_response ... ok</code>; (3) <code>tests/vault_smoke.rs</code> re-verified still green (task 12.3&#39;s own test, unaffected by this task&#39;s changes to <code>secure_storage</code>, which only added a test-only in-memory keyring backend shared by every module&#39;s tests).</p><hr><h4 id="✅-12-5-—-tier-3-native-handler-registry-tauri" tabindex="-1">✅ 12.5 — Tier 3 native handler registry (Tauri) <a class="header-anchor" href="#✅-12-5-—-tier-3-native-handler-registry-tauri" aria-label="Permalink to &quot;✅ 12.5 — Tier 3 native handler registry (Tauri)&quot;">​</a></h4><p><strong>Goal:</strong> The Tier 3 extension point (task 2.6) ported to Tauri commands, mirroring <code>apps/mobile/src/connectors/runtime/nativeHandlers.ts</code>.</p><p><strong>Deliverables:</strong></p><ul><li><code>executeConnectorCall</code>&#39;s <code>case 3</code> dispatching to Tauri commands, each gated by Tauri v2&#39;s own capabilities system rather than <code>isAllowed()</code> alone — belt-and-braces, matching research 0010&#39;s finding that this is the closer structural fit than Electron would have offered.</li><li>At least one real registered capability, the same proof-of-life role <code>device.info</code>/<code>expo-device</code> played for task 2.6 on mobile — a genuinely cross-platform one (e.g. OS version/hostname) rather than inventing a desktop-specific connector ahead of need.</li></ul><p><strong>Dependencies:</strong> Tasks 12.1, 12.4.</p><p><strong>Review checklist:</strong></p><ul><li>Revoking a Tier 3 connector&#39;s grant blocks its Tauri command from running, verified on-device (not just Jest-equivalent mocks) — the same bar task 2.6 set and met on the iOS Simulator.</li></ul><p><code>connectors/runtime/native_handlers.rs</code> mirrors <code>nativeHandlers.ts</code>: a private capability→handler map plus <code>native_handler_for()</code>. <code>device.info</code> (the same proof-of-life capability name mobile uses) is implemented with <code>sysinfo</code> — hostname + OS name + OS version, the cross-platform proxy research 0010 itself suggested, since mobile&#39;s <code>modelName</code>/<code>osName</code>/ <code>osVersion</code> triple has no desktop equivalent. <code>execute_connector_call</code>&#39;s Tier 3 branch (stubbed &quot;not implemented&quot; since it was written a task early, in 12.4) now mirrors <code>executeTier3</code> exactly: <code>is_allowed</code> → registry lookup → argument normalization → handler call, <code>Result&lt;String,String&gt;</code> mapped to <code>ExecutionResult::Ok</code>/<code>Err(HandlerError)</code>. One new Tauri command, <code>device_info</code>, wraps <code>execute_connector_call</code> directly rather than duplicating its gating logic, so the IPC path and any future internal caller (tool-routing, not built yet) share one source of truth.</p><p><strong>Belt-and-braces, for real, not just declared.</strong> This task also closed the gap 12.1/12.2/12.3 flagged and explicitly deferred here: Tauri v2&#39;s ACL only gates <em>plugin</em>-provided commands by default, so this app&#39;s own commands (<code>list_models</code>, <code>generate</code>, etc.) were reachable regardless of <code>capabilities/default.json</code> until now. <code>build.rs</code> now calls <code>tauri_build::try_build</code> with <code>Attributes::new().app_manifest(AppManifest::new() .commands(&amp;[...]))</code> listing every command this app registers (not just <code>device_info</code> — leaving the rest ungated would have been a half-measure), and <code>capabilities/default.json</code> grants each an individual <code>allow-&lt;command&gt;</code> permission — no wildcard, this repo&#39;s own stated convention. <strong>Found by an actual build failure, not assumed correct:</strong> the identifier format is kebab-case, not the snake_case the doc comment implies — <code>install_model</code>&#39;s autogenerated permission is <code>allow-install-model</code>, confirmed by <code>tauri-build</code> itself rejecting <code>allow-install_model</code> at build time (<code>invalid plugin or permission identifier ... identifiers can only include lowercase ASCII, hyphens</code>) before the correct spelling was written down.</p><p><strong>Verified on macOS, not on Windows or Linux — flagged rather than assumed,</strong> the same gap 12.1–12.4 recorded. <code>cargo fmt --check</code> and <code>cargo clippy --all-targets -- -D warnings</code> ran clean. <code>cargo test --lib</code> (45 tests) includes real, unmocked Tier 3 coverage — <code>device_info</code> returns real non-empty on-device text when granted, is refused <code>not-permitted</code> when never granted, and (matching the review checklist&#39;s own wording precisely) <code>revoking_a_tier3_grant_blocks_the_native_handler</code>: granted → succeeds, <code>revoke()</code>&#39;d → blocked, using the real <code>grants.rs</code>/<code>native_handlers.rs</code> code with no mocking at all (unlike the credential-touching tests elsewhere, <code>device.info</code> never touches the vault, so there&#39;s nothing to mock here). Separately, the real debug binary was built and launched (<code>scripts/ci/launch-smoke.js</code>, the same &quot;still running N seconds later&quot; bar 12.1 established) after wiring <code>build.rs</code>&#39;s new ACL mechanism, confirming the whole boot sequence — ACL generation included — works end to end, not just that <code>cargo check</code> passes. <strong>Gap flagged rather than faked:</strong> this environment has no way to drive a native window&#39;s WebKit inspector, so the literal &quot;invoke <code>device_info</code> from the devtools console&quot; step mobile&#39;s own iOS Simulator bar implies wasn&#39;t performed manually — the equivalent real coverage instead comes from the unmocked Rust-level test above plus the real build/launch check, which exercise the identical code path (<code>is_allowed</code> → registry → handler) without needing a hand click.</p><hr><h4 id="✅-12-6-—-packages-desktop-ui-initial-component-set" tabindex="-1">✅ 12.6 — <code>packages/desktop-ui</code> initial component set <a class="header-anchor" href="#✅-12-6-—-packages-desktop-ui-initial-component-set" aria-label="Permalink to &quot;✅ 12.6 — `packages/desktop-ui` initial component set&quot;">​</a></h4><p><strong>Goal:</strong> The component set task 12.7&#39;s chat UI (and any future desktop screen) is built from, matching <code>apps/mobile/src/design-system</code>&#39;s shape for React DOM.</p><p><strong>Deliverables:</strong></p><ul><li><code>ThemeProvider</code>, <code>Button</code>, <code>ChatBubble</code>, <code>ListItem</code>, <code>TextField</code>, <code>Toggle</code> built against <code>packages/design-tokens</code>, per that package&#39;s own README.</li></ul><p><strong>Dependencies:</strong> Task 12.1.</p><p><strong>Review checklist:</strong></p><ul><li>Each component renders correctly in at least two of the three WebView engines this app ships on (WebKit/macOS, WebView2/Windows) — the rendering parity research 0010 flagged as unmeasured, checked here rather than left open indefinitely.</li></ul><p>Also populated <code>packages/design-tokens</code> as part of this task — nothing else in the epic claimed that extraction, and <code>desktop-ui</code>&#39;s own deliverable (&quot;built against <code>packages/design-tokens</code>, per that package&#39;s own README&quot;) required it to exist first. Both packages were empty scaffolds beforehand, the same state <code>packages/core</code> was in before task 12.2. Styled via CSS Modules + CSS custom properties, no new styling-library dependency (none existed in this repo before this task); <code>ThemeProvider</code> sets every token as a <code>--sv-*</code> custom property from the live <code>Theme</code> object each render, so there&#39;s no parallel CSS copy of the palette to keep in sync by hand. This is also the first <code>packages/*</code> → <code>apps/*</code> workspace dependency exercised in this repo (<code>apps/desktop/package.json</code>&#39;s <code>&quot;desktop-ui&quot;: &quot;workspace:*&quot;</code>) — required adding <code>apps/desktop/src/vite-env.d.ts</code> (<code>/// &lt;reference types=&quot;vite/client&quot; /&gt;</code>), a genuine pre-existing gap from task 12.1&#39;s own scaffold that only surfaced once something actually imported a <code>.module.css</code> file through it.</p><p><strong>One necessary deviation from mobile, not an oversight:</strong> mobile&#39;s <code>Toggle</code> wraps React Native&#39;s native <code>Switch</code>, deliberately untinted — its own doc comment explains two attempts to theme it made dark mode <em>worse</em>. The web has no equivalent &quot;free, already-legible OS switch&quot; to defer to (<code>&lt;input type=&quot;checkbox&quot;&gt;</code> renders as a checkbox, not a switch, and isn&#39;t reliably restylable as one across engines), so desktop&#39;s <code>Toggle</code> is a themed <code>role=&quot;switch&quot;</code> button built from scratch instead.</p><p><strong>Verified — real browser, real DOM, not just a passing typecheck:</strong><code>pnpm typecheck</code>/<code>pnpm lint</code> clean workspace-wide. Ran <code>apps/desktop</code>&#39;s actual Vite dev server and viewed all five components in the sandboxed Browser pane: correct light/dark theming via CSS custom properties, correct accessibility tree (<code>Toggle</code> reports as <code>switch &quot;Notifications&quot;</code>, not a generic button — confirmed via the accessibility tree, not assumed from the JSX), zero console errors, and the full expected text content present via the rendered DOM. <strong>Honest gap:</strong> this is a real browser rendering real code, but it is not one of the three WebView engines the checklist actually asks about (WebKit/macOS, WebView2/Windows, WebKitGTK/Linux) — this environment has no way to launch or screenshot the real Tauri window, the same limitation 12.5 hit. So this verifies the components/tokens work, not cross-engine parity specifically — flagged rather than claimed.</p><hr><h4 id="✅-12-7a-—-grammar-constrained-tool-calling-in-the-rust-engine" tabindex="-1">✅ 12.7a — Grammar-constrained tool-calling in the Rust engine <a class="header-anchor" href="#✅-12-7a-—-grammar-constrained-tool-calling-in-the-rust-engine" aria-label="Permalink to &quot;✅ 12.7a — Grammar-constrained tool-calling in the Rust engine&quot;">​</a></h4><p><strong>Goal:</strong> Give the desktop <code>EngineAdapter</code> real tool-calling, so task 12.7&#39;s review checklist (&quot;a granted Tier 1 connector answers and is visibly marked as having done so&quot;) is something the engine can actually do, not something the chat UI would have to fake. Split out of task 12.7 rather than folded into it: mobile&#39;s tool-calling rides entirely on <code>llama.rn</code>&#39;s own jinja/chat-template machinery (<code>chatTemplates.jinja.defaultCaps.tools</code>, OpenAI-shaped <code>tools</code>/<code>tool_choice</code>/<code>tool_calls</code> passed straight through to <code>context.completion</code>), and <code>llama-cpp-2</code> — task 12.2&#39;s own crate choice — exposes none of that, only low-level GBNF grammar-sampler primitives (<code>LlamaSampler::grammar</code>) with no JSON-Schema→GBNF converter and no chat-template tool-capability introspection. Building both was real, separable engine work, not &quot;wire up a UI.&quot;</p><p><strong>Deliverables:</strong></p><ul><li><code>engine::grammar</code>: a JSON-Schema-subset → GBNF converter and a fixed decision-envelope grammar (<code>{&quot;answer&quot;: &quot;...&quot;}</code> / <code>{&quot;tool_call&quot;: {&quot;name&quot;: &quot;...&quot;, &quot;arguments&quot;: {...}}}</code>), built fresh per call from the tools offered.</li><li><code>engine::adapter</code>: wires the grammar into the sampler chain when <code>GenerateOptions.tools</code> is non-empty and parses the constrained output back into <code>GenerateResult.tool_calls</code>.</li><li><code>connectors::routing</code> (<code>route_message</code>, mirroring <code>connectors/routing/route.ts</code>) and <code>connectors::orchestration</code> (<code>generate_with_connectors</code>, mirroring <code>settings/connectorOrchestration.ts</code>) — the routing-decision and connector-execution-with-fallback logic task 12.7&#39;s chat UI will call into.</li><li>A <code>generate_chat</code> Tauri command (<code>off</code>/<code>auto</code>/<code>required</code> connector modes) exposing all of the above through IPC, ahead of task 12.7&#39;s UI existing to call it.</li></ul><p><strong>Dependencies:</strong> Tasks 12.2, 12.4.</p><p><strong>Review checklist:</strong></p><ul><li>A real on-device model, given a granted Tier 1 connector and forced tool use, actually emits a grammar-constrained tool call — executed for real against a local test server — and the reply comes back tagged with the connector&#39;s name. Proven by a real model, not a mock or a fake engine.</li></ul><p><strong>Deliberate protocol difference from mobile:</strong> rather than reproduce llama.cpp&#39;s native <code>&lt;tool_call&gt;</code>/chat-template tool syntax, this ships its own fixed JSON decision envelope, constrained by a GBNF grammar this module builds per call. This makes tool-calling here <strong>model-agnostic</strong> — it works for any instruction-following model, not only ones whose GGUF chat template happens to declare tool support — so <code>EngineInfo.tool_capable</code> is unconditionally <code>true</code> once a model is loaded, unlike mobile&#39;s template-dependent flag. Mobile&#39;s fourth <code>RoutingDecision</code> case, <code>unsupported</code> (reached when the model&#39;s template can&#39;t tool-call), is consequently unreachable here and isn&#39;t in the Rust <code>RoutingDecision</code> enum at all. <strong>Scope limit, checked not assumed:</strong> the grammar builder supports only flat JSON-Schema objects with <code>string</code>/<code>number</code>/<code>integer</code>/<code>boolean</code> properties; an unsupported schema shape fails loudly (<code>GrammarError</code>) rather than building a grammar that can&#39;t represent it.</p><p><strong>Two real, on-device-only bugs this task&#39;s own review checklist caught — neither visible to any unit test, both pre-existing in code earlier tasks shipped:</strong></p><ol><li><code>generate_inner</code> called <code>sampler.accept(token)</code> manually <em>after</em><code>sampler.sample()</code>, which already accepts internally (<code>llama_sampler_sample</code> is documented as &quot;sample and accept&quot;). Harmless for the old stateless temp/dist-only chain, but a real double-accept once a stateful grammar sampler joined it — the grammar&#39;s parse position ran two tokens ahead of what was actually generated, eventually walking past a satisfied rule into an empty parse state and crashing (<code>GGML_ASSERT(!stacks.empty())</code>, in llama.cpp&#39;s own grammar code) on the next sample call. Fixed by removing the redundant manual <code>accept</code>.</li><li><code>EngineAdapter::generate()</code> never cleared the context&#39;s KV cache between calls, so a second call on the same loaded model (routing&#39;s tool-decision call followed by orchestration&#39;s final-answer call, both against one context) started its prompt batch at position 0 while the cache still held entries through the first call&#39;s last position — llama.cpp rejects that as non-consecutive sequence positions and decode fails outright. Fixed with <code>ctx.clear_kv_cache()</code> at the start of every <code>generate()</code> call. Invisible before this task because nothing before it ever called <code>generate()</code> twice on one loaded context.</li></ol><p><strong>Verified — real model, real grammar, real network, not mocks:</strong> <code>cargo fmt --check</code> / <code>cargo clippy --all-targets -- -D warnings</code> clean. Full <code>cargo test</code> (62 unit tests, no <code>--ignored</code>) covers the grammar builder, routing decisions (unknown tool / not-permitted / malformed-arguments / granted paths, against a canned <code>FakeEngine</code> implementing a new <code>GenerativeEngine</code> trait — the same testability seam <code>models::LoadedModelHandle</code> already established), and orchestration (required-with-nothing-offered short-circuit, blocked-decision fallback, execution-failure fallback, and a successful tool-call round trip against a real local TCP server). <code>cargo test --test tool_calling_smoke -- --ignored --nocapture</code> on-device (macOS): a real Qwen2.5 0.5B model, forced to call the Search tool against a granted connector fixture pointed at a local test server, produced a real grammar-constrained <code>tool_call</code> JSON, executed it for real, and returned a final answer tagged <code>connector: Some(&quot;Search&quot;)</code> — this is what caught both bugs above. <code>cargo test --test engine_smoke -- --ignored --nocapture</code> re-run afterward to confirm the KV-cache fix didn&#39;t regress the plain (no-tools) generation path.</p><hr><h4 id="✅-12-7-—-minimal-offline-chat-ui" tabindex="-1">✅ 12.7 — Minimal offline chat UI <a class="header-anchor" href="#✅-12-7-—-minimal-offline-chat-ui" aria-label="Permalink to &quot;✅ 12.7 — Minimal offline chat UI&quot;">​</a></h4><p><strong>Goal:</strong> Enough UI to exercise tasks 12.2–12.5 and 12.7a end to end and verify them the way this repo&#39;s own convention requires — a real behavior check, not a green test suite — mirroring the role mobile&#39;s task 1.3 played inside its own Core Inference &amp; Chat epic rather than inside App Shell.</p><p><strong>Deliverables:</strong></p><ul><li>A single chat screen: model selection, message input/output, and the same in-chat connector-provenance marker mobile&#39;s task 2.5 established (<code>connector?: string</code> on the reply), calling task 12.7a&#39;s <code>generate_chat</code> command rather than reimplementing routing/orchestration in the UI layer.</li></ul><p><strong>Dependencies:</strong> Tasks 12.2, 12.4, 12.6, 12.7a.</p><p><strong>Review checklist:</strong></p><ul><li>A fully offline conversation works end to end on-device with no connector installed, and a granted Tier 1 connector answers and is visibly marked as having done so — the desktop equivalent of task 2.5&#39;s own review bar.</li></ul><p><strong>Implementation:</strong> <code>apps/desktop/src/chat/ChatScreen.tsx</code>, mirroring <code>apps/mobile/src/chat/screens/ChatScreen.tsx</code>&#39;s <code>send()</code> (streaming via per-token events, final text/connector taken from the resolved result rather than trusted from the accumulated stream — mobile&#39;s own test for a reply that streamed zero tokens) and <code>apps/mobile/src/models/screens/ ModelsScreen.tsx</code>&#39;s install-then-load dispatch — folded into one screen rather than two, since desktop has no navigation/settings shell yet (<code>core-port.md</code>&#39;s own &quot;deliberately out of scope&quot; note) to put a separate Models screen behind. <code>apps/desktop/src/lib/tauri.ts</code> is a thin, typed <code>invoke</code>/<code>listen</code> wrapper layer, with every field&#39;s casing checked against its actual Rust <code>serde</code> attributes rather than assumed uniform (<code>generate_ chat</code>&#39;s own request struct is snake_case on the wire, unlike the camelCase <code>ManagedModel</code>/<code>GenerateChatResponse</code> — getting this wrong fails silently, as an absent optional field, not a deserialize error).</p><p><strong>New Tauri commands, added because the checklist needs them, not speculatively:</strong> <code>connector_status</code> and <code>set_search_connector_granted</code> — desktop has no Settings → Connectors screen (out of scope for this epic), so the chat screen&#39;s own <code>Toggle</code> next to the Search connector&#39;s <code>ListItem</code> is the only lever a user has over consent, backed directly by <code>connectors::permissions::grant</code>/<code>revoke</code>. <code>CommandError</code> gained a <code>Vault</code> variant (<code>secure_storage::VaultError</code> didn&#39;t derive <code>Serialize</code> — nothing had crossed the IPC boundary needing it before <code>revoke</code>&#39;s own error type).</p><p><strong>Verified:</strong></p><ul><li><code>pnpm --filter desktop exec tsc --noEmit</code> / <code>eslint .</code> clean; <code>pnpm exec prettier --check</code> clean. <code>cargo fmt --check</code> / <code>cargo clippy --all-targets -- -D warnings</code> / <code>cargo test --lib</code> (62 tests) clean after the two new commands.</li><li>Real Vite dev server viewed in a real browser: correct dark-theme rendering, correct initial state (<code>&quot;Loading models…&quot;</code>, disabled composer, <code>&quot;Choose a model first&quot;</code> placeholder), zero console errors, and no crash from <code>invoke()</code> rejecting outside a real Tauri runtime (this pane has no Tauri backend to talk to, so this exercises rendering and graceful degradation, not the commands themselves).</li><li>The real debug binary (<code>cargo build</code>, then <code>scripts/ci/launch-smoke.js</code>) launched and stayed running past the check window with all 14 commands registered and ACL-gated — proves <code>build.rs</code>&#39;s <code>COMMANDS</code> list and <code>capabilities/default.json</code> stayed consistent (a mismatch is a build- or setup-time failure, per task 12.5&#39;s own established pattern), not just that the frontend compiled.</li><li>The underlying behavior this screen&#39;s checklist cares about — offline generation, and a granted connector answering and getting tagged — was already proven for real, on-device, against the exact <code>generate_chat</code>/<code>generate_with_connectors</code> code path this screen calls, by task 12.7a&#39;s own <code>tests/tool_calling_smoke.rs</code>.</li><li><strong>Honest gap:</strong> this environment has no way to drive the actual native Tauri window (no simulator/browser-automation tool reaches a real WebView2/WebKit app window here, the same limitation every desktop task since 12.5 has flagged), so clicking &quot;Send&quot; in the real, running app and watching a reply arrive was not performed by hand. The verification above is the strongest chain available without that: real rendering, a real running binary with correct IPC wiring, and the real on-device generation path already proven by 12.7a — not a substitute for actually watching it happen, and flagged as such rather than claimed.</li></ul><hr><h4 id="✅-12-8-—-writing-assist-modes-desktop-port" tabindex="-1">✅ 12.8 — Writing-assist modes (desktop port) <a class="header-anchor" href="#✅-12-8-—-writing-assist-modes-desktop-port" aria-label="Permalink to &quot;✅ 12.8 — Writing-assist modes (desktop port)&quot;">​</a></h4><p><strong>Goal:</strong> Port mobile&#39;s task 1.4 — the concrete scenario-1 use case (brainstorm, grammar-fix, rewrite tone, draft from bullet points) — to desktop chat. Closes the single largest UX gap a feature audit found between the two apps: desktop&#39;s chat screen has no writing-assist modes at all today, only plain chat with <code>auto</code>/<code>off</code> connector routing.</p><p><strong>What already exists and needs no change</strong> (confirmed by reading the code, not assumed): <code>ConnectorMode</code> already carries <code>&#39;required&#39;</code> end-to-end — TS type → <code>generate_chat</code>&#39;s Rust enum → <code>ToolChoice::Required</code> — desktop&#39;s connector layer already supports Search-style forcing, only <code>ChatScreen.tsx</code> has never sent it. <code>generateChat()</code>&#39;s wrapper already accepts <code>temperature</code>; per-mode temperature needs no API change. <code>ManagedModel.parametersB</code> is already fetched by <code>ChatScreen.tsx</code> via <code>listModels()</code> on mount and currently discarded — the model-size data the risk banner needs is already in memory, just not stored into state.</p><p><strong>Decided: modes stay entirely client-side, mirroring mobile&#39;s own architecture exactly</strong> — no new Tauri command, no new field on <code>GenerateChatRequest</code>. A mode&#39;s system prompt is a <code>ChatMessage{role: &#39;system&#39;, content}</code> prepended into the same <code>messages</code> array already sent, identical to how mobile&#39;s <code>ChatScreen.send()</code> builds <code>history</code> today; <code>generate_chat</code>&#39;s Rust side needs zero changes since system-prompt- via-message is already the only mechanism that exists at the engine layer (confirmed: no <code>system_prompt</code> field exists on <code>GenerateOptions</code> on either platform). This makes 12.8 a frontend-only task.</p><p><strong>Deliverables:</strong></p><ul><li><code>apps/desktop/src/chat/modes.ts</code> — a direct port of <code>apps/mobile/src/chat/modes/modes.ts</code>&#39;s six modes (<code>plain</code>, <code>search</code>, <code>brainstorm</code>, <code>grammar</code>, <code>tone</code>, <code>draft</code>), same <code>id</code>/<code>label</code>/<code>banner</code>/ <code>systemPrompt</code>/<code>temperature</code>/<code>usesHistory</code>/<code>cautionBelowB</code> fields, same prompt copy and temperatures — these were empirically tuned against the smallest catalog model (mobile&#39;s own review checklist), not invented fresh here.</li><li><code>ChatScreen.tsx</code>: <code>modeId</code> state; <code>send()</code> derives <code>connectorMode</code> (<code>search</code> → <code>&#39;required&#39;</code>, <code>plain</code> → <code>&#39;auto&#39;</code>, else <code>&#39;off&#39;</code>) and <code>temperature</code> from the active mode, prepends the mode&#39;s system message when set, and drops history when <code>usesHistory</code> is false — mirroring mobile&#39;s <code>send()</code> exactly, including the &quot;mode&#39;s prompt is prepended fresh each turn, not stored in message history&quot; behavior (so switching modes takes effect on the next reply, not retroactively).</li><li>A <code>ModeBar</code>-equivalent: a new, bespoke component (not a <code>desktop-ui</code> primitive — mobile&#39;s own <code>ModeBar</code> lives inside <code>ChatScreen.tsx</code>, not its design system either, since no other screen needs mode chips), row of selectable chips above the composer, in the existing unused space between the message list and <code>&lt;footer&gt;</code>. No existing <code>desktop-ui</code> component has selected-state chip semantics (<code>Button</code> has no <code>active</code>/<code>selected</code> variant) — needs its own CSS module, <code>aria-pressed</code> (or equivalent) for the selected state, and an accessible name following mobile&#39;s exact convention (<code>&quot;${label} mode&quot;</code>) so the two platforms&#39; screen-reader behavior matches.</li><li>A risk banner mirroring mobile&#39;s <code>OfflineBanner</code> risk branch: shown when <code>mode.cautionBelowB !== null &amp;&amp; activeModelParamsB !== null &amp;&amp; activeModelParamsB &lt; mode.cautionBelowB</code> — today only <code>draft</code> at <code>&lt; 1</code>. Copy adapted from mobile&#39;s (<code>&quot;{model} is small enough to invent details that were not in your notes...&quot;</code>), with the &quot;switch to a larger model&quot; call-to-action pointing at desktop&#39;s own <code>onNavigate(&#39;models&#39;)</code> instead of mobile&#39;s Models tab.</li></ul><p><strong>Dependencies:</strong> Task 12.7 (the chat screen this extends).</p><p><strong>Review checklist</strong> (mirrors mobile&#39;s task 1.4 bar — measured behavior, not just &quot;the UI renders&quot;):</p><ul><li>Each mode produces a materially different, appropriate transformation of the same input text, measured against whatever model is actually loaded on this machine at the time (mobile&#39;s own review found real, model-size-dependent failure modes — brainstorm restating one idea several ways, draft inventing a figure below 1B — these are worth re-checking on desktop&#39;s own inference path, not assumed identical just because the prompts are copied).</li><li>A mode&#39;s system prompt reaches the model only via the current turn, not retroactively rewriting prior turns already in <code>messages</code> state.</li><li><code>connectorMode</code> sent to <code>generate_chat</code> is <code>&#39;required&#39;</code> for Search, <code>&#39;off&#39;</code> for every non-plain, non-search mode, <code>&#39;auto&#39;</code> for plain chat — verified by inspecting the actual request, not just trusting the code path.</li><li>The draft risk banner appears only for <code>draft</code> mode below the 1B threshold and is absent for every other mode regardless of model size.</li><li>Revoking the Search connector&#39;s permission does not affect any other mode&#39;s availability, and switching away from Search mode does not require the connector to still be granted.</li></ul><p><strong>Verified:</strong> <code>apps/desktop/src/chat/modes.ts</code> is a byte-for-byte port of mobile&#39;s six modes (prompts, temperatures, <code>usesHistory</code>, <code>cautionBelowB</code> all unchanged). <code>pnpm typecheck</code> / <code>pnpm lint</code> / <code>pnpm exec prettier --check</code> clean. Real Vite dev server viewed in a real browser: all 6 chips render with the exact <code>&quot;${label} mode&quot;</code> accessible names mobile&#39;s own tests assert on (<code>&quot;Fix grammar mode&quot;</code>, <code>&quot;Search mode&quot;</code>, etc.), clicking a chip flips <code>aria-pressed</code> on exactly one chip at a time (confirmed via <code>document.querySelectorAll</code>, not just visually), and the header subtitle composes the active mode&#39;s <code>banner</code> text after the base sentence exactly when <code>modeId !== &#39;plain&#39;</code> — mirroring mobile&#39;s own conditional-join composition. Zero console errors. A real debug build (<code>pnpm tauri build --debug --no-bundle</code>, embedding the new frontend bundle) and <code>scripts/ci/launch-smoke.js</code> confirm the real binary still launches and stays running with <code>ChatScreen.tsx</code>&#39;s changed import surface — <code>cargo clippy --all-targets -- -D warnings</code> also clean (no Rust changed, cheap insurance regardless).</p><p><strong>Honest gap:</strong> this sandboxed environment has no Accessibility/ screen-capture access, so — the same limitation task 14.3 flagged — neither the real native Tauri window nor a synthetic mocked-IPC round trip could be driven here: browser navigation always creates a fresh JS context, so there&#39;s no way to pre-seed a mock <code>window.__TAURI_INTERNALS__</code> bridge before the app&#39;s own module evaluates in this tooling (confirmed by testing it, not assumed). The actual <code>connector_mode</code>/<code>temperature</code>/ system-prompt-and-history request shape sent to <code>generate_chat</code> per mode was verified by code review and typechecking, not by inspecting a live request — a genuine gap from the review checklist&#39;s own bar, not silently skipped. The UI-rendering, selection-state, and build/launch verification above is the strongest chain available without that.</p><hr><h4 id="✅-12-9-—-debug-only-runtime-offline-tripwire" tabindex="-1">✅ 12.9 — Debug-only runtime offline tripwire <a class="header-anchor" href="#✅-12-9-—-debug-only-runtime-offline-tripwire" aria-label="Permalink to &quot;✅ 12.9 — Debug-only runtime offline tripwire&quot;">​</a></h4><p><strong>Goal:</strong> Close a real defense-in-depth asymmetry a feature audit found: mobile has a <em>runtime</em> check (<code>offlineTripwire.ts</code>, replaces the network globals with throwing stubs, dev-only) that catches a network violation the static checks miss; desktop had only structural guarantees (Tier 1&#39;s origin allowlist) proven by tests, nothing that runs and actively fails against a <em>new</em> unsanctioned code path.</p><p><strong>Deliverables:</strong></p><ul><li>New <code>net_guard.rs</code>: a debug-only guard hooking <code>reqwest</code>&#39;s DNS resolution (the closest real interception point Rust offers — there is no ambient global like <code>fetch</code> to monkey-patch). <code>guarded_client_builder()</code> attaches a custom resolver that refuses to resolve any hostname unless the calling task is inside an <code>allow_network(...)</code> scope (<code>tokio::task_local</code>-backed — the direct analogue of mobile&#39;s own <code>allowNetworkForConnector</code>).</li><li>Both real network egress points in the app wired through it: <code>connectors::runtime::execute::client()</code>/its one <code>.execute()</code> call, and <code>models::download</code>&#39;s <code>run_download</code>/<code>lib.rs</code>&#39;s <code>install_model</code>.</li><li>New <code>clippy.toml</code> (<code>disallowed-methods</code> banning <code>reqwest::Client::new</code>/<code>::builder()</code> outside <code>net_guard.rs</code>) plus <code>lib.rs</code>&#39;s <code>#![warn(clippy::disallowed_methods)]</code> — the closest available analogue to mobile&#39;s ESLint restricted-globals rule, closing (partially, not fully) the gap that the guard only protects code that opts in.</li><li>New <a href="./../../desktop-network-audit.html"><code>docs/desktop-network-audit.md</code></a>, structured like mobile&#39;s own <code>docs/network-audit.md</code>, honestly scoped to what desktop actually has.</li></ul><p><strong>Dependencies:</strong> Task 12.4 (the connector runtime this wraps), Task 12.2 (the model download path this wraps).</p><p><strong>Review checklist:</strong></p><ul><li>A request outside <code>allow_network(...)</code> is actually blocked, with the guard&#39;s own error, not a generic connection failure; a request inside the scope actually reaches a real server; the guard re-arms after a scope ends rather than becoming a one-way latch.</li></ul><p><strong>Decided: an honest, narrower mechanism, not a claimed port.</strong> Rust&#39;s lack of an ambient network global means this cannot match mobile&#39;s coverage, and the docs say so rather than implying otherwise. Two blind spots stated plainly in both <code>net_guard.rs</code>&#39;s own doc comment and the new audit doc: a request to a literal IP address skips DNS resolution entirely (reproduced, not hypothetical — the existing <code>tests/connector_dispatch.rs</code> and <code>download.rs</code>&#39;s own cancellation tests both use <code>127.0.0.1</code> and pass regardless of <code>allow_network</code>, which is exactly this blind spot in practice); and the guard only protects <code>reqwest::Client</code>s built via <code>guarded_client_builder()</code> — nothing catches a stray <code>reqwest::Client::new()</code> except the clippy lint, which can be silenced at the call site. reqwest&#39;s own default resolver (<code>GaiResolver</code>) turned out to be <code>pub(crate)</code>, not reachable from outside its own crate — discovered only by attempting to use it, not by reading the docs first — so the allowed path delegates to <code>tokio::net::lookup_host</code> instead, the same underlying OS resolution mechanism called directly.</p><p><strong>Verified:</strong> <code>cargo fmt --check</code>/<code>clippy --all-targets -- -D warnings</code> clean (confirmed the lint actually fires: a scratch <code>reqwest::Client::new()</code> call was temporarily added, clippy flagged it by name, then it was removed before committing). <code>cargo test --lib</code> (75/75, including 3 new <code>net_guard</code> tests against a real local <code>TcpListener</code> server reached via <code>localhost</code> — not <code>127.0.0.1</code> — to actually exercise DNS resolution: one proving an unguarded request is blocked with the tripwire&#39;s own error text pulled from the full <code>source()</code> chain, one proving a guarded request reaches the real server, one proving the guard re-arms after the scope ends). <code>cargo test --test connector_dispatch</code> still passes — its own IP-literal request is unaffected by the guard, confirming that documented blind spot in practice. Real debug binary build (<code>pnpm tauri build --debug --no-bundle</code>) + <code>scripts/ci/launch-smoke.js</code> confirm the guard doesn&#39;t break real model loading at startup. <strong>Honest gap:</strong> this mechanism does not achieve mobile&#39;s coverage — it is a real, executable check where there was previously none, not full parity with an ambient-global interception Rust has no equivalent primitive for.</p><hr><h4 id="✅-12-10-—-rust-model-management-test-coverage" tabindex="-1">✅ 12.10 — Rust model-management test coverage <a class="header-anchor" href="#✅-12-10-—-rust-model-management-test-coverage" aria-label="Permalink to &quot;✅ 12.10 — Rust model-management test coverage&quot;">​</a></h4><p><strong>Goal:</strong> Close a fresh feature audit&#39;s top-ranked finding: desktop&#39;s Rust ports of mobile&#39;s model-management logic had effectively zero test coverage where mobile&#39;s TypeScript equivalents are thoroughly tested with mocks — <code>models/manager.rs</code> (0 tests vs. mobile&#39;s 233-line <code>manager.test.ts</code>), <code>models/verify.rs</code> (0 vs. 234 lines across two files), <code>models/store.rs</code>, <code>models/catalog.rs</code>, <code>models/device.rs</code> (0 each), and <code>engine/adapter.rs</code> (441 lines, 0 tests, vs. mobile&#39;s <code>engine.test.ts</code> mocking <code>llama.rn</code> for load-failure/OOM/abort paths). <code>models/download.rs</code> and the connector/vault/manifest modules were already well covered and are out of scope here.</p><p><strong>Real constraint, confirmed by reading the code before writing anything:</strong><code>engine/adapter.rs</code>&#39;s <code>EngineAdapter</code> is hard-wired to real <code>llama-cpp-2</code> bindings with no injectable trait seam — mobile mocks <code>llama.rn</code> because it&#39;s a JS import <code>jest.mock()</code> can intercept; Rust has no equivalent for a linked native library. Full parity with mobile&#39;s mocked coverage isn&#39;t achievable here.</p><p><strong>Deliverables:</strong></p><ul><li><code>models/verify.rs</code>: 9 tests — <code>assert_verifiable</code>&#39;s three branches, <code>verify_file</code>&#39;s size/sha256/md5 success and mismatch paths, and a missing-file storage error — using well-known SHA-256/MD5 test vectors for fixed content (<code>&quot;hello world&quot;</code>), not invented values.</li><li><code>models/store.rs</code>: 11 tests — path helpers, <code>is_installed</code>, <code>list_installed</code> (excludes <code>.part</code> files, reports real size), <code>remove_model</code> (deletes both files, no-ops cleanly), the active-model-id round trip including the &quot;stored id but file gone → degrades to None, doesn&#39;t error&quot; case, and <code>assert_space_for</code> against real disk space (<code>u64::MAX / 2</code> for the failure case).</li><li><code>models/catalog.rs</code>: 5 tests — non-empty, unique ids, every entry carries a verifiable checksum, <code>find_in_catalog</code> hit/miss.</li><li><code>models/device.rs</code>: 5 tests — <code>estimate_peak_bytes</code>&#39; formula checked independently, <code>total_memory_bytes()</code> returns real data on this machine, and <code>fit_for_device</code>&#39;s three <code>Fit</code> branches hit deterministically by sizing a synthetic <code>CatalogEntry</code> relative to the <em>real</em><code>total_memory_bytes()</code> read at test time, not a stubbed value.</li><li><code>models/manager.rs</code>: 11 tests via a new <code>FakeEngine</code> (implementing the existing <code>LoadedModelHandle</code> trait, which exists specifically for this — mirrors <code>connectors/routing/route.rs</code>&#39;s own <code>FakeEngine</code> naming for an unrelated trait) — <code>list()</code> against real scratch-dir installed state, <code>remove()</code>&#39;s &quot;unloads the engine and clears the stored choice only for the <em>active</em> model&quot; behavior (and its inverse: leaves both alone for a non-active model), <code>mark_active</code>/<code>preferred_model_id</code> round-trip and fallback, <code>prepare_switch</code>&#39;s three branches, <code>descriptor()</code> hit/miss.</li><li><code>engine/adapter.rs</code>: 1 test covering 4 scenarios — <code>generate()</code> before any load → <code>NoModelLoaded</code> (no file needed at all); <code>load()</code> against a small garbage-bytes file → <code>ModelLoadFailed</code>, a real llama.cpp GGUF parser rejection, confirmed in the test&#39;s own stderr output, not silently no-op&#39;d; <code>load()</code> against a <strong>sparse</strong> file (<code>File::set_len</code> reports a huge logical size with no real disk blocks allocated) sized past <code>total_memory_bytes() * 0.5</code> → <code>OutOfMemory</code>, proving <code>classify()</code>&#39;s size-vs-RAM arithmetic for real; <code>unload()</code> on a never-loaded adapter is a safe no-op.</li></ul><p><strong>Dependencies:</strong> None new.</p><p><strong>Review checklist:</strong></p><ul><li>The new tests exercise the real success/failure branches of each function (not just &quot;it compiles&quot;), and the <code>engine/adapter.rs</code> tests are confirmed to hit real <code>llama-cpp-2</code> failure paths, not a silent no-op.</li></ul><p><strong>Decided: one shared <code>EngineAdapter</code> across all four <code>engine/adapter.rs</code> scenarios, not four separate <code>#[test]</code>s.</strong><code>LlamaBackend::init()</code> is a process-global singleton — a second call anywhere in the process fails with <code>BackendAlreadyInitialized</code>, found by actually writing four separate tests first and watching three of them fail with exactly that error (<code>cargo test</code> runs tests concurrently in one process). Rather than threading a <code>OnceLock</code>/lock through every test for a constraint that only bites once per process, one <code>EngineAdapter</code> is created once and <code>.unload()</code> reset between phases inside a single <code>#[test]</code> — simpler than the alternative for what it&#39;s guarding against.</p><p><strong>Honest, documented gap:</strong> the &quot;generation already in progress&quot; branch (<code>EngineAdapter</code>&#39;s <code>generating</code> <code>AtomicBool</code>) is only reachable after a <em>successful</em> load, which needs real GGUF weights this environment doesn&#39;t have — left unverified here rather than faked, the same class of on-device-only gap this app&#39;s docs already carry elsewhere.</p><p><strong>Verified:</strong> <code>cargo fmt --check</code>/<code>clippy --all-targets -- -D warnings</code> clean. <code>cargo test --lib</code> — 117/117 (75 existing + 42 new), including the <code>engine/adapter.rs</code> test whose stderr output shows real <code>gguf_init_from_ reader: invalid magic characters</code> rejections from llama.cpp itself for both the garbage-file and sparse-file scenarios. Real debug binary build (<code>pnpm tauri build --debug --no-bundle</code>) + <code>scripts/ci/launch-smoke.js</code> confirm nothing in the six touched modules broke real startup.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./../../desktop-network-audit.html">Desktop network audit</a> — task 12.9&#39;s own audit document, mirroring mobile&#39;s <code>network-audit.md</code></li><li><a href="./shell.html">Desktop Shell</a> — epic 9, the shell-technology decision this depends on</li><li><a href="./../../research/0010-desktop-shell-technology.html">research 0010</a></li><li><a href="./../mobile/core-inference-chat.html">Core Inference &amp; Chat</a> (epic 1) and <a href="./../mobile/connector-framework.html">Connector Framework</a> (epic 2) — the mobile epics this one ports</li></ul>',134)])])}const m=o(n,[["render",c]]);export{u as __pageData,m as default};
